H.background();
// Spherical mirror:  1/f = 1/do + 1/di,  with f = R/2
// Concave: f > 0 (converging). Convex: f < 0 (diverging).
const f = (Math.abs(P.f) < 0.2 ? (P.f < 0 ? -0.2 : 0.2) : P.f);  // focal length (cm)
const ho = P.ho;                                                  // object height (cm)
const af = Math.abs(f);
// Plot window adapts to |f| so the object, image, F and C stay on-screen for
// every focal length the slider can reach.
const v = H.plot2d({ xMin: -3.6 * af - 1, xMax: 2.4 * af + 1.5, yMin: -5, yMax: 5 });
v.grid(); v.axes();
// Object distance sweeps as a multiple of |f| (always outside F, so the real
// image stays finite and bounded) and moves through its whole range.
const do_ = af * (2.5 + 0.7 * Math.sin(t * 0.6));    // in [1.8|f|, 3.2|f|], always > |f|
const denom = (1 / f) - (1 / do_);
const di = Math.abs(denom) < 1e-5 ? 1e6 : 1 / denom; // image distance (cm)
const M = -di / do_;                                 // magnification
const hi = M * ho;                                   // image height (cm)
const R = 2 * f;                                      // radius of curvature
// Object & mirror sit in FRONT of the mirror = the NEGATIVE-x side; the mirror
// vertex is at the origin. For a concave mirror (f>0) F and C are real and lie
// in front, so they plot at x = -f and x = -R = -2f. (Convex flips the signs,
// putting F and C behind, as the negatives of negative f naturally give.)
const xF = -f, xC = -R;
// Mirror surface as a shallow arc that always bulges toward the FRONT (object
// side, -x): concave curves away from the object, convex toward it. Using |R|
// for the sag and the sign of f for the direction keeps the cup correct both ways.
const arc = [];
const sag = (f > 0 ? -1 : 1);   // concave opens toward -x; convex bulges toward -x
for (let yy = -4; yy <= 4.001; yy += 0.2) arc.push([sag * (yy * yy) / (2 * Math.abs(R)), yy]);
v.path(arc, { color: H.colors.violet, width: 3 });
v.line(0, -4, 0, 4, { color: H.colors.grid, width: 1, dash: [3, 3] });
v.dot(xF, 0, { r: 5, fill: H.colors.good });         // focal point F
v.dot(xC, 0, { r: 4, fill: H.colors.axis });         // center of curvature C
// Object arrow at x = -do_, image arrow at x = -di (real in front, virtual behind).
const xi = -di;
v.arrow(-do_, 0, -do_, ho, { color: H.colors.accent, width: 3 });
v.arrow(xi, 0, xi, hi, { color: H.colors.warn, width: 3 });
// Ray 1: parallel to axis to the mirror, then reflects THROUGH F.
// Object tip, mirror point (0,ho), F=(-f,0) and the image tip are colinear, so
// the segment (0,ho)->(xi,hi) genuinely passes through F.
v.line(-do_, ho, 0, ho, { color: H.colors.yellow, width: 1.5 });
v.line(0, ho, xi, hi, { color: H.colors.yellow, width: 1.5, dash: di < 0 ? [4, 4] : null });
// Ray 2: aimed at the center of curvature C; it strikes the mirror along the
// radius and reflects straight back on itself. Object tip, C and image tip are
// colinear, so this single line through C reaches the image tip.
v.line(-do_, ho, xi, hi, { color: H.colors.accent2, width: 1.5, dash: di < 0 ? [4, 4] : null });
v.dot(-do_, ho, { r: 5, fill: H.colors.accent });
v.dot(xi, hi, { r: 5, fill: H.colors.warn });
H.text(f > 0 ? "Concave mirror:  1/f = 1/do + 1/di" : "Convex mirror:  1/f = 1/do + 1/di", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("f=" + f.toFixed(1) + "cm  do=" + do_.toFixed(1) + "  di=" + di.toFixed(1) + "  M=" + M.toFixed(2) + (di > 0 ? "  real/inverted" : "  virtual/upright"), 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "object", color: H.colors.accent }, { label: "image", color: H.colors.warn }, { label: "F", color: H.colors.good }], H.W - 150, 28);
